impl Document {
    pub(crate) fn compare_bsw_entry_relationship(
        &self,
        _other: &Document,
        a: &BswEntryRelationship,
        b: &BswEntryRelationship,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_bsw_entry_relationship_type() != b.get_bsw_entry_relationship_type() {
            return Err(format!("{path}: BSW_ENTRY_RELATIONSHIP_TYPE mismatch"));
        }
        if a.get_from_ref() != b.get_from_ref() {
            return Err(format!("{path}: FROM_REF mismatch"));
        }
        if a.get_to_ref() != b.get_to_ref() {
            return Err(format!("{path}: TO_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_bsw_entry_relationship_set(
        &self,
        other: &Document,
        a: &BswEntryRelationshipSet,
        b: &BswEntryRelationshipSet,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        let list_a = a.get_bsw_entry_relationships();
        let list_b = b.get_bsw_entry_relationships();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: BSW_ENTRY_RELATIONSHIPS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.bsw_entry_relationships.get(*x).ok_or_else(|| {
                format!("{path}.BSW_ENTRY_RELATIONSHIPS[{index}]: id not found in own arena")
            })?;
            let y = other.bsw_entry_relationships.get(*y).ok_or_else(|| {
                format!("{path}.BSW_ENTRY_RELATIONSHIPS[{index}]: id not found in other arena")
            })?;
            self.compare_bsw_entry_relationship(
                other,
                x,
                y,
                &format!("{path}.BSW_ENTRY_RELATIONSHIPS[{index}]"),
            )?;
        }
        Ok(())
    }

    pub(crate) fn compare_bsw_module_client_server_entry(
        &self,
        other: &Document,
        a: &BswModuleClientServerEntry,
        b: &BswModuleClientServerEntry,
        path: &str,
    ) -> Result<(), String> {
        self.compare_referrable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_encapsulated_entry_ref() != b.get_encapsulated_entry_ref() {
            return Err(format!("{path}: ENCAPSULATED_ENTRY_REF mismatch"));
        }
        if a.get_is_reentrant() != b.get_is_reentrant() {
            return Err(format!("{path}: IS_REENTRANT mismatch"));
        }
        if a.get_is_synchronous() != b.get_is_synchronous() {
            return Err(format!("{path}: IS_SYNCHRONOUS mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_bsw_module_dependency(
        &self,
        other: &Document,
        a: &BswModuleDependency,
        b: &BswModuleDependency,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        if a.get_target_module_id() != b.get_target_module_id() {
            return Err(format!("{path}: TARGET_MODULE_ID mismatch"));
        }
        if a.get_target_module_ref() != b.get_target_module_ref() {
            return Err(format!("{path}: TARGET_MODULE_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_bsw_module_entry(
        &self,
        other: &Document,
        a: &BswModuleEntry,
        b: &BswModuleEntry,
        path: &str,
    ) -> Result<(), String> {
        self.compare_atp_blueprintable(other, a.base(), b.base(), path)?;
        let list_a = a.get_arguments();
        let list_b = b.get_arguments();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: ARGUMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .sw_service_args
                .get(*x)
                .ok_or_else(|| format!("{path}.ARGUMENTS[{index}]: id not found in own arena"))?;
            let y = other
                .sw_service_args
                .get(*y)
                .ok_or_else(|| format!("{path}.ARGUMENTS[{index}]: id not found in other arena"))?;
            self.compare_sw_service_arg(other, x, y, &format!("{path}.ARGUMENTS[{index}]"))?;
        }
        if a.get_bsw_entry_kind() != b.get_bsw_entry_kind() {
            return Err(format!("{path}: BSW_ENTRY_KIND mismatch"));
        }
        if a.get_call_type() != b.get_call_type() {
            return Err(format!("{path}: CALL_TYPE mismatch"));
        }
        if a.get_execution_context() != b.get_execution_context() {
            return Err(format!("{path}: EXECUTION_CONTEXT mismatch"));
        }
        if a.get_function_prototype_emitter() != b.get_function_prototype_emitter() {
            return Err(format!("{path}: FUNCTION_PROTOTYPE_EMITTER mismatch"));
        }
        if a.get_is_reentrant() != b.get_is_reentrant() {
            return Err(format!("{path}: IS_REENTRANT mismatch"));
        }
        if a.get_is_synchronous() != b.get_is_synchronous() {
            return Err(format!("{path}: IS_SYNCHRONOUS mismatch"));
        }
        if a.get_return_type() != b.get_return_type() {
            return Err(format!("{path}: RETURN_TYPE mismatch"));
        }
        if a.get_role() != b.get_role() {
            return Err(format!("{path}: ROLE mismatch"));
        }
        if a.get_service_id() != b.get_service_id() {
            return Err(format!("{path}: SERVICE_ID mismatch"));
        }
        if a.get_sw_service_impl_policy() != b.get_sw_service_impl_policy() {
            return Err(format!("{path}: SW_SERVICE_IMPL_POLICY mismatch"));
        }
        Ok(())
    }
}
